function save(){try{localStorage.setItem('arco-v1',JSON.stringify(state));}catch{toast('Your browser could not save progress. Keep this tab open.');}}
function toast(t){$('#toast').textContent=t;$('#toast').style.opacity=1;setTimeout(()=>$('#toast').style.opacity=0,3000);}
function open(html){cleanup();cleanup=()=>{};$('#modalBody').innerHTML=html;if(!modal.open)modal.showModal();}
function close(){cleanup();modal.close();}$('.close').onclick=close;modal.addEventListener('cancel',()=>cleanup());modal.addEventListener('click',e=>{if(e.target===modal)close();});
function completed(id){if(!state.done.includes(id)){state.done.push(id);save();toast('Milestone saved. A little closer to your first instrument.');}render();}
